import { cn, normalizeTone } from '@cascivo/core/pure'
import type { ToneInput } from '@cascivo/core'
import type { HTMLAttributes } from 'react'
import styles from './status.module.css'

/** Canonical tone → the value Status's stylesheet keys on. */
const TONE_CLASS: Record<string, string> = {
  neutral: 'neutral',
  info: 'info',
  success: 'success',
  warning: 'warning',
  danger: 'error',
}

export interface StatusProps extends HTMLAttributes<HTMLSpanElement> {
  /**
   * Severity tone. Accepts the catalog-wide `Tone` vocabulary
   * (`neutral | info | success | warning | danger`) plus Status's historical spellings
   * (`error`, `destructive`, `default`).
   *
   * To name this type in your own code — a `Record<DeployState, Tone>` is the usual shape —
   * import it: `import type { Tone } from '@cascivo/react/types'` on the prebuilt path, or
   * from `@cascivo/core` if you copied the source. Do not add `@cascivo/core` to a prebuilt
   * app just for this; it is a transitive dependency there.
   */
  status?: ToneInput
  /**
   * Pulses the dot — gated behind prefers-reduced-motion: no-preference
   *
   * @defaultValue `false`
   * @see the component manifest
   */
  pulse?: boolean
}

export function Status({
  status = 'neutral',
  pulse = false,
  className,
  children,
  ...props
}: StatusProps) {
  return (
    <span
      data-status={TONE_CLASS[normalizeTone(status)] ?? status}
      data-pulse={pulse ? '' : undefined}
      className={cn(styles['status'], className as string | undefined)}
      {...props}
    >
      <span aria-hidden="true" className={styles['dot']} />
      {children}
    </span>
  )
}

@layer cascivo.component {
  .status {
    display: inline-flex;
    align-items: center;
    gap: var(--cascivo-space-2);
    font-family: var(--cascivo-font-sans);
    font-size: var(--cascivo-text-sm);
    color: var(--cascivo-color-text);
    line-height: var(--cascivo-leading-tight);

    &[data-status='success'] .dot {
      background-color: var(--cascivo-color-success);
    }

    &[data-status='warning'] .dot {
      background-color: var(--cascivo-color-warning);
    }

    &[data-status='error'] .dot {
      background-color: var(--cascivo-color-error);
    }

    &[data-status='info'] .dot {
      background-color: var(--cascivo-color-info);
    }

    &[data-status='neutral'] .dot {
      background-color: var(--cascivo-color-text-muted);
    }
  }

  .dot {
    inline-size: 0.5rem;
    block-size: 0.5rem;
    border-radius: var(--cascivo-radius-full);
    flex-shrink: 0;
  }

  @media (prefers-reduced-motion: no-preference) {
    .status[data-pulse] .dot {
      animation: global(cascivo-pulse) 2s var(--cascivo-ease-in-out) infinite;
    }
  }
}

import type { ComponentMeta } from '@cascivo/core'

export const meta: ComponentMeta = {
  name: 'Status',
  description: 'Colored dot with a label communicating the state of a system or entity',
  category: 'display',
  clientJs: 'none',
  states: [],
  variants: ['success', 'warning', 'error', 'info', 'neutral'],
  sizes: [],
  props: [
    {
      name: 'status',
      description: 'Status state.',
      type: "'success' | 'warning' | 'error' | 'info' | 'neutral'",
      required: false,
      default: 'neutral',
    },
    {
      name: 'pulse',
      type: 'boolean',
      required: false,
      default: 'false',
      description: 'Pulses the dot — gated behind prefers-reduced-motion: no-preference',
    },
  ],
  tokens: [
    '--cascivo-color-success',
    '--cascivo-color-warning',
    '--cascivo-color-error',
    '--cascivo-color-info',
    '--cascivo-color-text-muted',
    '--cascivo-color-text',
    '--cascivo-radius-full',
  ],
  accessibility: {
    role: 'none',
    wcag: '2.2-AA',
    keyboard: [],
  },
  examples: [
    { title: 'Default', code: '<Status>Unknown</Status>' },
    { title: 'Success', code: '<Status status="success">Operational</Status>' },
    {
      title: 'Pulsing',
      code: '<Status status="info" pulse>Deploying</Status>',
      description: 'The pulse animation respects prefers-reduced-motion',
    },
  ],
  dependencies: ['@cascivo/core'],
  tags: ['status', 'indicator', 'dot', 'badge'],
  intent: {
    whenToUse: [
      'Communicating the live state of a system or entity (operational, deploying, down)',
      'Pairing a colored dot with a text label for an at-a-glance state',
      'Drawing attention to an active/changing state with an optional pulse',
    ],
    whenNotToUse: [
      'A static category or count label — use Badge',
      'An identity thumbnail with presence — use Avatar with its status prop',
    ],
    antiPatterns: [
      {
        bad: '<Status status="success" /> with no label',
        good: '<Status status="success">Operational</Status>',
        why: 'A bare colored dot conveys nothing to color-blind or screen-reader users; always pair with text',
      },
    ],
    related: [
      {
        name: 'Badge',
        relationship: 'alternative',
        reason: 'Badge labels categories; Status reflects live state with a dot',
      },
      {
        name: 'Avatar',
        relationship: 'alternative',
        reason: 'Avatar embeds presence status on an identity',
      },
    ],
    a11yRationale:
      'Meaning is carried by the text label, never by the dot color alone; the pulse animation is gated behind prefers-reduced-motion: no-preference so it never animates for users who opt out',
    content: {
      tone: 'Short state words (Operational, Degraded, Down)',
      notes: 'Label the state, not the color',
    },
    flexibility: [
      {
        area: 'pulse',
        level: 'flexible',
        note: 'Enable pulse only for actively-changing states',
      },
      {
        area: 'token names',
        level: 'strict',
        note: 'State colors must resolve to --cascivo-color-success/warning/error/info',
      },
    ],
  },
}
